function lev(a,b){const m=a.length,n=b.length;if(Math.abs(m-n)>2)return 9;const d=Array.from({length:m+1},(_,i)=>[i]);for(let j=1;j<=n;j++)d[0][j]=j;
  for(let i=1;i<=m;i++)for(let j=1;j<=n;j++)d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1));return d[m][n]}
function parse(q){
  const r={specs:new Set(),conds:new Set(),langs:new Set(),gender:null,accepting:false,online:false,near:false,names:[],fixed:[],unknown:[],labels:[]};
  let t=" "+q.toLowerCase().replace(/[’]/g,"'").replace(/[^a-z0-9'\/\- ]/g," ").replace(/\s+/g," ").trim()+" ";
  const take=(re)=>{let hit=false;t=t.replace(re,()=>{hit=true;return " "});return hit};
  if(take(/ near me /))r.near=true;
  if(take(/ (accepting|taking) new patients | new patients /))r.accepting=true;
  if(take(/ (book|schedule|scheduling) online | online (booking|scheduling) /))r.online=true;
  SYN.slice().sort(()=>0).forEach(([keys,map])=>{keys.slice().sort((a,b)=>b.length-a.length).forEach(k=>{
    const kk=k.replace(/[’]/g,"'");const re=new RegExp(" "+kk.replace(/[.*+?^${}()|[\]\\\/]/g,"\\$&")+" ");
    if(re.test(t)){t=t.replace(re," ");(map.specs||[]).forEach(s=>r.specs.add(s));(map.conds||[]).forEach(c=>r.conds.add(c));if(map.label)r.labels.push(map.label)}})});
  if(take(/ (female|woman|women) /))r.gender="Female"; else if(take(/ (male|man|men) /))r.gender="Male";
  LANGS.forEach(l=>{const re=new RegExp(" "+l.toLowerCase()+"(-| )?(speaking|speaker)? ");if(re.test(t)){t=t.replace(re," ");r.langs.add(l)}});
  SPECS.forEach(s=>{const k=" "+s.toLowerCase()+" ";if(t.includes(k)){t=t.replace(k," ");r.specs.add(s)}});
  CONDS.forEach(c=>{const k=" "+c.toLowerCase()+" ";if(t.includes(k)){t=t.replace(k," ");r.conds.add(c)}});
  const toks=t.split(" ").filter(w=>w&&!STOP.has(w));
  const vocab=[...SPECS.map(s=>[s.toLowerCase(),{specs:[s]},s]),...CONDS.map(c=>[c.toLowerCase(),{conds:[c]},c])];
  SYN.forEach(([keys,map])=>keys.forEach(k=>{if(k.length>=5)vocab.push([k,map,map.specs?map.specs[0]:map.conds[0]])}));
  toks.forEach(w=>{
    const nm=PROV.filter(p=>p.last.toLowerCase().startsWith(w)||p.first.toLowerCase().startsWith(w));
    if(nm.length&&w.length>=2){r.names.push(w);return}
    if(w.length>=4){
      let best=null;vocab.forEach(([v,map,label])=>{v.split(" ").concat([v]).forEach(part=>{if(part.length<4)return;const d=lev(w,part);const lim=part.length>7?2:1;if(d<=lim&&(!best||d<best.d))best={d,map,label,part}})});
      if(best){(best.map.specs||[]).forEach(s=>r.specs.add(s));(best.map.conds||[]).forEach(c=>r.conds.add(c));r.fixed.push([w,best.part]);return}
    }
    r.unknown.push(w);
  });
  return r;
}
function matches(p,pq){
  const topical=pq.specs.size||pq.conds.size;
  if(topical&&!(p.specs.some(s=>pq.specs.has(s))||p.conds.some(c=>pq.conds.has(c))))return false;
  if(pq.names.length&&!pq.names.every(w=>p.first.toLowerCase().startsWith(w)||p.last.toLowerCase().startsWith(w)))return false;
  if(pq.unknown.length)return false;
  return true;
}
function relevance(p,pq){return (p.specs.some(s=>pq.specs.has(s))?3:0)+(p.conds.filter(c=>pq.conds.has(c)).length*2)+(p.accepting?1:0)+(p.online?.5:0)}

