/* ---------- Distance ---------- */
function distTo(p){if(!S.loc)return null;return Math.min(...p.locs.map(k=>Math.hypot(LOCS[k].x-S.loc.x,LOCS[k].y-S.loc.y)))}
function nearestLoc(p){if(!S.loc)return LOCS[p.locs[0]];return p.locs.map(k=>LOCS[k]).sort((a,b)=>Math.hypot(a.x-S.loc.x,a.y-S.loc.y)-Math.hypot(b.x-S.loc.x,b.y-S.loc.y))[0]}
const fmtMi=d=>d==null?"":(d<10?d.toFixed(1):Math.round(d))+" mi";
const locDist=l=>S.loc?Math.hypot(l.x-S.loc.x,l.y-S.loc.y):null;

/* ---------- Search pipeline ---------- */
function filterList(list,f){
  return list.filter(p=>(!f.specs.size||p.specs.some(s=>f.specs.has(s)))&&(!f.conds.size||p.conds.some(c=>f.conds.has(c)))
    &&(!f.langs.size||p.langs.some(l=>f.langs.has(l)))&&(f.gender==="any"||p.gender===f.gender)&&(!f.hosp.size||p.hosp.some(h=>f.hosp.has(h)))
    &&(f.dist==="any"||!S.loc||distTo(p)<=+f.dist)&&(!f.accepting||p.accepting)&&(!f.online||p.online));
}
function results(f=S.filters){
  const pq=S.pq||parse("");
  let list=filterList(PROV.filter(p=>matches(p,pq)),f);
  const az=(a,b)=>a.last.localeCompare(b.last)||a.first.localeCompare(b.first);
  const byRel=(a,b)=>relevance(b,pq)-relevance(a,pq)||(S.loc?distTo(a)-distTo(b):0)||az(a,b);
  if(S.sort==="distance"&&S.loc)list.sort((a,b)=>distTo(a)-distTo(b)||az(a,b));
  else if(S.sort==="az")list.sort(az);
  else if(S.sort==="featured")list.sort((a,b)=>(b.featured-a.featured)||byRel(a,b));
  else list.sort(byRel);
  return list;
}
function filterCount(f=S.filters){return f.specs.size+f.conds.size+f.langs.size+f.hosp.size+(f.gender!=="any")+(f.dist!=="any")+f.accepting+f.online}
function addRecent(q){S.recent=[q,...S.recent.filter(x=>x.toLowerCase()!==q.toLowerCase())].slice(0,5);store.set("recent",S.recent)}
function runSearch(q,opts={}){
  q=q.trim();S.q=q;S.pq=parse(q);
  if(!opts.keepFilters)S.filters=blankFilters();
  const pq=S.pq;
  pq.langs.forEach(l=>S.filters.langs.add(l));if(pq.gender)S.filters.gender=pq.gender;if(pq.accepting)S.filters.accepting=true;if(pq.online)S.filters.online=true;
  if(q)addRecent(q);
  if(pq.near&&!S.loc){S.pendingNear=true}
  if(S.tab!=="find"){S.tab="find";markTab()}
  const st=S.stacks.find;if(st[st.length-1].v!=="results")st.splice(1);
  if(st[st.length-1].v!=="results"){push({v:"results"})}else{render("fade")}
  load();
  if(S.pendingNear){S.pendingNear=false;setTimeout(()=>useMyLocation(),rm()?0:350)}
}
let loadT;
function load(){
  clearTimeout(loadT);S.loading=true;renderResultsBody();
  loadT=setTimeout(()=>{S.loading=false;renderResultsBody();announceResults()},S.data==="slow"?2600:700);
}
function announceResults(){
  if(S.data==="error")return sayPolite("Couldn’t load doctors. Try again.");
  if(S.data==="offline")return sayPolite("You’re offline.");
  const n=results().length;sayPolite(n?`${n} doctor${n>1?"s":""} found`:"No doctors match. Suggestions are below.");
}

/* ---------- Navigation ---------- */
/* One transition everywhere (pages, tabs, search, menu, sheets): fade in while growing from the middle; close in reverse. Nothing slides in from a side. */
function push(entry){const st=S.stacks[S.tab];st[st.length-1].scroll=view.scrollTop;
  st.push(entry);render("push",{scroll:0});
  focusTitle()}
function pop(){const st=S.stacks[S.tab];if(st.length<2)return;const gone=st.pop();
  render("pop",{scroll:st[st.length-1].scroll||0});focusTitle()}
function switchTab(t,reset){
  if(t===S.tab&&!reset){if(S.stacks[t].length>1){S.stacks[t].splice(1);render("pop",{scroll:0})}return}
  const st=S.stacks[S.tab];st[st.length-1].scroll=view.scrollTop;
  S.tab=t;if(reset)S.stacks[t].splice(1);markTab();render("fade",{scroll:top().scroll||0});
  sayPolite((TABS.find(x=>x[0]===t)||[0,TITLES[t]])[1]);
}
function focusTitle(){setTimeout(()=>{const h=$("#appbar .ttl")||$("#view h1");if(h){h.setAttribute("tabindex","-1");h.focus({preventScroll:true})}},rm()?0:50)}

