function markTab(){$$("#tabbar .tab").forEach(b=>b.dataset.tab===S.tab?b.setAttribute("aria-current","page"):b.removeAttribute("aria-current"));placeInd()}
function placeInd(){const ind=$("#tab-ind"),cur=$('#tabbar .tab[aria-current="page"]');if(!ind)return;ind.classList.toggle("none",!cur);if(!cur)return;

  const pr=$(".pill",cur).getBoundingClientRect(),br=$("#tabbar").getBoundingClientRect(),k=br.width/$("#tabbar").offsetWidth||1;
  ind.style.transform=`translate(${((pr.left-br.left)/k-$("#tabbar").clientLeft).toFixed(2)}px,${((pr.top-br.top)/k-$("#tabbar").clientTop).toFixed(2)}px)`;if(!ind.classList.contains("ready"))requestAnimationFrame(()=>requestAnimationFrame(()=>ind.classList.add("ready")))}

