/* ---------- Favorites ---------- */
function toggleFav(id,src){
  const p=PBY[id];const on=!isSaved(id),prev=S.saved.length;
  S.saved=on?[...S.saved,id]:S.saved.filter(x=>x!==id);store.set("saved",S.saved);
  renderTabbar();const cnt=$("#tabbar .cnt");if(cnt){if(prev)rollNumber(cnt,prev,S.saved.length);else bump(cnt)}
  const t=top();
  if(t.v==="saved"&&!on){const card=$(`[data-card="${id}"]`);if(card&&canMove())collapseOut(card,()=>rerenderKeep());else rerenderKeep()}
  else{
    $$(`[data-action="fav"][data-id="${id}"]`).forEach(b=>{
      if(b.dataset.style==="hero"){b.setAttribute("aria-pressed",String(on));b.innerHTML=paSave(on)}
      else b.outerHTML=favBtn(p);
    });
    $$(`[data-action="fav"][data-id="${id}"]`).forEach(b=>{if(on){b.classList.add("popping","filling");setTimeout(()=>b.classList.remove("popping","filling"),480)}});
    if(src)$(`[data-action="fav"][data-id="${id}"]${src==="hero"?'[data-style="hero"]':':not([data-style])'}`)?.focus();
  }
  toast(on?`${drName(p)} saved to Favorites`:`${drName(p)} removed from Favorites`,"done",{label:"Undo",fn:()=>toggleFav(id)});
}

function toggleLocFav(id){
  const l=LOCS[id],on=!isLocSaved(id);
  S.savedLocs=on?[...S.savedLocs,id]:S.savedLocs.filter(x=>x!==id);store.set("saved-locs",S.savedLocs);renderTabbar();
  if(top().v==="saved"&&!on){const r=$(`[data-loc="${id}"]`);if(r&&canMove())collapseOut(r,()=>rerenderKeep());else rerenderKeep()}
  else $$(`[data-action="fav-loc"][data-id="${id}"]`).forEach(b=>{b.setAttribute("aria-pressed",String(on));b.setAttribute("aria-label",on?`Remove ${l.n} from saved`:`Save ${l.n}`);b.innerHTML=on?heart(24):ic("favorite");if(on&&canMove()){b.classList.add("popping","filling");setTimeout(()=>b.classList.remove("popping","filling"),480)}});
  toast(on?`${l.n} saved to Favorites`:`${l.n} removed from Favorites`,"done",{label:"Undo",fn:()=>toggleLocFav(id)});
}

/* ---------- Global search overlay (kept from the home prototype) ---------- */
/* The search screen grows out of the field that opened it, and shrinks back into it */
let searchSrc=null;
function srcInset(src,layer){const r=src.getBoundingClientRect(),L=layer.getBoundingClientRect();
  return `inset(${Math.max(0,r.top-L.top)}px ${Math.max(0,L.right-r.right)}px ${Math.max(0,L.bottom-r.bottom)}px ${Math.max(0,r.left-L.left)}px round ${r.height/2}px)`}
function openSearch(q){
  lastFocus=document.activeElement;const s=$("#search");s.hidden=false;setInert(true);
  $("#q").value=q||"";renderSearch(q||"");
  const src=lastFocus&&lastFocus.closest&&lastFocus.closest(".search-entry");searchSrc=src&&src.getBoundingClientRect().height?src:null;
  if(canMove()){
    s.animate(ZOOM_IN_KF,{duration:ZOOM_IN,easing:EASE_IOS});
    stagger($$("#search-body .lbl-h,#search-body .chip,#search-body .card,#search-body .btn"),160,30,12);
  }
  setTimeout(()=>$("#q").focus(),rm()?0:80);
}
function closeSearch(cb){
  const s=$("#search");if(s.hidden){cb&&cb();return}
  const done=()=>{s.hidden=true;$("#q").value="";$("#q-clear").hidden=true;setInert(false);if(!cb&&lastFocus&&document.contains(lastFocus))lastFocus.focus();cb&&cb()};
  if(!canMove())return done();
  const a=s.animate(ZOOM_OUT_KF,{duration:ZOOM_OUT+40,easing:"ease-in"});
  a.onfinish=done;
}
/* Search screen: Saved providers and Search history share one card behind a two-way toggle (both on this device) */
function yoursHTML(){
  const t=S.yours||"saved",ps=S.saved.map(id=>PBY[id]).filter(Boolean),chev=ic("chevron_right",20);
  const tab=(k,l,n)=>`<button class="yt-btn" role="tab" id="yt-${k}" aria-controls="yt-panel" aria-selected="${t===k}" tabindex="${t===k?0:-1}" data-action="yours" data-k="${k}">${l}${n?` <span class="yt-n">${n}</span>`:""}</button>`;
  const body=t==="saved"
    ?(ps.length?ps.map(p=>`<button class="row" data-action="gs-profile" data-id="${p.id}">${avatar(p,40)}<span class="rt"><b>${esc(name(p))}</b><span>${esc(p.spec)} · ${esc(LOCS[p.locs[0]].n)}</span></span>${chev}</button>`).join("")
      :`<button class="row" data-action="search-saved">${well("favorite")}<span class="rt"><b>No saved providers yet</b><span>Tap the heart on a provider to save them</span></span>${chev}</button>`)
    :(S.recent.length?S.recent.map(r=>`<button class="row" data-action="search-all" data-q="${esc(r)}">${well("history")}<span class="rt"><b>${esc(r)}</b></span>${chev}</button>`).join("")
      :`<div class="row" style="cursor:default">${well("history")}<span class="rt"><b>No searches yet</b><span>Your recent searches show here</span></span></div>`);
  return `<section class="res-group yours" aria-label="Saved providers and search history">
    <div class="yt-bar"><div class="yt" role="tablist" aria-label="Show">${tab("saved","Saved providers",ps.length)}${tab("history","Search history",S.recent.length)}</div></div>
    <div class="card list" role="tabpanel" id="yt-panel" aria-labelledby="yt-${t}">${body}</div>
    <div class="grp-h"><p class="fine">On this device</p>${t==="history"&&S.recent.length?`<button class="btn btn-ghost btn-sm" data-action="clear-history">Clear</button>`:""}</div></section>`;
}
/* Provider filters right in search: tune button beside the field (count badge); a summary line with Clear when any are on */
function syncSearchFilters(){const n=filterCount(),b=$("#search-filters");if(!b)return;
  b.innerHTML=ic("tune",20)+(n?`<span class="sf-n" aria-hidden="true">${n}</span>`:"");b.setAttribute("aria-label",n?`Filters, ${n} on`:"Filters");b.classList.toggle("on",!!n)}
function sfSummary(){const n=filterCount();if(!n)return"";const f=S.filters,parts=[...f.specs,...f.conds,...f.langs,...f.hosp];
  if(f.gender!=="any")parts.push(f.gender==="f"?"Female":f.gender==="m"?"Male":f.gender);if(f.dist!=="any")parts.push(`Within ${f.dist} miles`);if(f.accepting)parts.push("Accepting new patients");if(f.online)parts.push("Online scheduling");
  return `<div class="sf-sum" role="group" aria-label="Provider filters">${ic("tune",20)}<span><b>${n} filter${n>1?"s":""} on</b> ${esc(parts.slice(0,3).join(", "))}${parts.length>3?` and ${parts.length-3} more`:""}</span><button class="btn btn-ghost btn-sm" data-action="search-clear-filters">Clear</button></div>`}
function renderYours(focusTab){const y=$("#search-body .yours");if(!y)return;y.outerHTML=yoursHTML();if(focusTab)$(`#yt-${S.yours}`)?.focus()}
function renderSearch(q){
  const b=$("#search-body");q=q.trim();$("#q-clear").hidden=!q;
  if(!q){b.innerHTML=sfSummary()+yoursHTML()+`<section class="res-group" aria-labelledby="gtop-h"><h2 class="lbl-h" id="gtop-h">Top searches</h2><div class="chips chips-row">${GS_TOP.map(t=>`<button class="chip chip-sm" data-action="search-term" data-q="${t}">${ic("trending_up",16)}${t}</button>`).join("")}</div></section>
     <section class="res-group" aria-labelledby="by-h"><h2 class="lbl-h" id="by-h">Search for</h2><div class="card list">${Object.values(KIND).map(([l,g,d])=>`<div class="row" style="cursor:default">${well(g)}<span class="rt"><b>${l}</b><span>${d}</span></span></div>`).join("")}</div></section>`;return}
  const pq=parse(q);const saveP=S.pq;S.pq=pq;const provs=results(S.filters);S.pq=saveP;
  const words=q.toLowerCase().split(/\s+/);
  const other=GS_OTHER.filter(r=>{const hay=(r.t+" "+r.s+" "+r.kw).toLowerCase();return words.some(w=>w.length>2&&hay.includes(w))||[...pq.specs,...pq.conds].some(s=>hay.includes(s.toLowerCase().split(" ")[0]))});
  const groups=[["provider",provs.slice(0,3)],...["location","content","resource"].map(k=>[k,other.filter(r=>r.k===k).slice(0,3)])].filter(([,l])=>l.length);
  b.innerHTML=sfSummary()+(groups.length?groups.map(([k,l])=>`<section class="res-group" aria-labelledby="g-${k}"><h2 class="lbl-h" id="g-${k}">${KIND[k][0]}</h2><div class="card list">${
     k==="provider"?l.map(p=>`<button class="row" data-action="gs-profile" data-id="${p.id}">${avatar(p,40)}<span class="rt"><b>${hl(name(p),q)}</b><span>${esc(p.spec)} · ${esc(LOCS[p.locs[0]].n)}</span></span>${ic("chevron_right",20)}</button>`).join("")
     +(provs.length>3?`<button class="row" data-action="search-all" data-q="${esc(q)}"><span class="rt"><b>See all ${provs.length} doctors</b></span>${ic("chevron_right",20)}</button>`:"")
     :l.map(r=>`<button class="row" data-action="search-pick" data-msg="${esc(r.t)}">${well(KIND[k][1])}<span class="rt"><b>${hl(r.t,q)}</b><span>${esc(r.s)}</span></span>${ic("chevron_right",20)}</button>`).join("")}</div></section>`).join("")
    :`<div class="card state">${well("search_off",48)}<h2>No matches for “${esc(q)}”</h2><p>Try a specialty, such as cardiology, a condition, or a clinic name.</p></div>`)
    +`<button class="btn btn-secondary btn-block" data-action="search-all" data-q="${esc(q)}">${ic("stethoscope",20)}<span>Search Find care for “${esc(q)}”</span></button>`;
  sayPolite(groups.length?"Results updated":"No results");
}
