/* ---------- Motion layer ---------- */
const canMove=()=>!rm();
const EASE_IOS="cubic-bezier(0.32,0.72,0,1)";
const views=$("#views");

/* Screen transitions: snapshot the outgoing screen, build the new one, then move both */
const ZOOM_IN=420,ZOOM_OUT=200,ZOOM_IN_KF=[{opacity:0,transform:"scale(.94)"},{opacity:1,transform:"scale(1)"}],ZOOM_OUT_KF=[{opacity:1,transform:"scale(1)"},{opacity:0,transform:"scale(.94)"}];
function screenTransition(kind,opts,build){
  $$(".ghost-wrap",views).forEach(g=>g.remove());view.getAnimations().forEach(a=>a.cancel());view.classList.remove("lift");
  if(!kind||!canMove()){build();return}
  const y=view.scrollTop,wrap=document.createElement("div"),g=view.cloneNode(true),dim=document.createElement("div");
  wrap.className="ghost-wrap";wrap.setAttribute("aria-hidden","true");wrap.inert=true;dim.className="ghost-dim";
  g.removeAttribute("id");g.removeAttribute("tabindex");g.removeAttribute("aria-label");$$("[id]",g).forEach(e=>e.removeAttribute("id"));
  wrap.append(g,dim);
  if(kind==="push")views.insertBefore(wrap,view);else{wrap.classList.add("top");views.appendChild(wrap)}
  g.scrollTop=y;
  build();
  /* The app's single transition: what leaves fades out; what arrives fades in while growing from the middle (scale .94 to 1) */
  wrap.classList.remove("top");wrap.style.zIndex="3";
  const a=wrap.animate([{opacity:1},{opacity:0}],{duration:ZOOM_OUT,easing:"ease-out",fill:"forwards"});
  view.animate(ZOOM_IN_KF,{duration:ZOOM_IN,easing:EASE_IOS,fill:"backwards"});
  a.onfinish=()=>{wrap.remove();view.classList.remove("lift")};
}
function animateAppbar(kind){
  if(!kind||!canMove())return;const t=$("#appbar .ttl"),b=$('#appbar [data-action="back"]');
  const dx=0;
  if(t)t.animate([{opacity:0,transform:`translate3d(${dx}px,0,0)`},{opacity:1,transform:"none"}],{duration:420,easing:EASE_IOS});
  if(b&&kind==="push")b.animate([{opacity:0},{opacity:1}],{duration:300,easing:"ease-out"});
}
function heroIntro(){
  if(!canMove())return;const al=$(".alerts",view);if(al)al.animate([{opacity:0,transform:"translate3d(0,-12px,0)"},{opacity:1,transform:"none"}],{duration:640,delay:520,easing:EASE_IOS,fill:"backwards"});[".hero-copy","#hero-search",".hero .top-s"].forEach((sel,i)=>{const el=$(sel,view);if(el)el.animate([{opacity:0,transform:"translate3d(0,20px,0)"},{opacity:1,transform:"none"}],{duration:760,delay:80+i*90,easing:EASE_IOS,fill:"backwards"})});
}

/* Scroll-linked motion: items below the fold are driven by scroll position; items on screen settle in once */
const SD_SEL=[".mod",".p-sec",".pcard",".fc-body>.grp",".res-body>.card",".res-body>.grp",".res-body>.mychart",".res-body>.notice",".res-sum",".blog-row",".blog-lead",".loc-card",".pad>.notice",".state",".v-inner>.fine"].join(",");
let sdList=[];
function layoutTop(el){let y=0;while(el&&el!==view){y+=el.offsetTop;el=el.offsetParent}return y}
function markScroll(root,animate,baseDelay){
  sdList=sdList.filter(x=>document.contains(x.el)&&view.contains(x.el));
  const vh=view.clientHeight,y=view.scrollTop;let n=0;
  const items=[];
  $$(SD_SEL,root).forEach(el=>{
    if(el.classList.contains("sd")||el.closest(".ghost-wrap"))return;
    const tiles=el.querySelector(".tiles");
    if(tiles){const head=el.querySelector(".mod-head");if(head)items.push([head,0]);$$(".tile",tiles).forEach((t,i)=>items.push([t,(i%2)*.08+Math.floor(i/2)*.04]));}
    else items.push([el,0]);
  });
  items.forEach(([el,d])=>{
    el.classList.add("sd");const top=layoutTop(el)-y,intro=top<vh;
    if(intro&&animate&&canMove())el.animate([{opacity:0,transform:"translate3d(0,32px,0)"},{opacity:1,transform:"none"}],{duration:720,delay:baseDelay+Math.min(n++,7)*55+d*300,easing:EASE_IOS,fill:"backwards"});
    /* Section-level heading that rises out of a mask as the section arrives (only for sections that arrive by scrolling) */
    const hd=intro?null:el.querySelector(":scope>.sec-h,:scope>.mod-head .sec-h,:scope>h3,:scope>.lbl-h,:scope>.grp-h .lbl-h");
    sdList.push({el,d,intro,hd});
  });
  applyScroll();
}
function applyScroll(){
  const vh=view.clientHeight,y=view.scrollTop,move=canMove();
  const sticky=$(".res-head",view)||$(".fc-head",view),edge=sticky?sticky.offsetHeight:0;
  for(const it of sdList){
    const el=it.el,hd=it.hd;
    if(!move){el.style.opacity="";el.style.transform="";if(hd){hd.style.clipPath="";hd.style.transform=""}continue}
    const top=layoutTop(el)-y,h=el.offsetHeight;
    /* Enter: rise, grow, and fade in over the first third of the screen (reverses on the way back) */
    let e=1;if(!it.intro){let p=(vh-top-it.d*vh*.3)/(vh*.34);p=p<0?0:p>1?1:p;e=1-Math.pow(1-p,3)}
    /* Exit: once the section's top passes the top edge, it recedes behind the next section */
    let x=(edge-top)/Math.max(96,Math.min(h,vh*.6));x=x<0?0:x>1?1:x;x=x*x*(3-2*x);
    const sc=(.94+.06*e)*(1-.05*x),ty=(1-e)*64+x*24,op=e*(1-.7*x);
    el.style.opacity=op>=.999?"":op.toFixed(3);
    el.style.transform=e>=1&&x<=0?"":`translate3d(0,${ty.toFixed(1)}px,0) scale(${sc.toFixed(4)})`;
    if(hd){let e2=(e-.25)/.75;e2=e2<0?0:e2>1?1:e2;const k=(1-e2)*100;
      hd.style.clipPath=k>.5?`inset(0 0 ${k.toFixed(1)}% 0)`:"";hd.style.transform=k>.5?`translate3d(0,${k.toFixed(1)}%,0)`:""}
  }
}

/* Per-frame scroll effects */
let scrollRaf=0;
function onScroll(){
  cancelAnimationFrame(scrollRaf);scrollRaf=requestAnimationFrame(()=>{
    const y=view.scrollTop,move=canMove(),t=top().v;
    const fh=$(".fc-head",view);$("#appbar").classList.toggle("scrolled",y>4&&!fh);if(fh)fh.classList.toggle("raised",y>4);
    applyScroll();
    const rh=$(".res-head",view);if(rh)rh.classList.toggle("raised",y>4);
    if(t==="home"){
      const copy=$(".hero-copy",view),au=$(".hero .aurora",view),yy=Math.min(Math.max(y,0),320);
      if(copy){copy.style.transform=move?`translate3d(0,${(yy*.35).toFixed(1)}px,0)`:"";copy.style.opacity=move?Math.max(0,1-yy/220).toFixed(3):""}
      if(au)au.style.transform=move?`translate3d(0,${(yy*.5).toFixed(1)}px,0)`:"";
      const vh=view.clientHeight;
      $$(".campaign",view).forEach(c=>{const off=(layoutTop(c)-y-vh/2);const s1=$(".shape1",c),s2=$(".shape2",c);
        if(s1)s1.style.transform=move?`translate3d(0,${(off*-.12).toFixed(1)}px,0)`:"";if(s2)s2.style.transform=move?`translate3d(0,${(off*.08).toFixed(1)}px,0)`:""});
    }
    if(t==="profile"){
      const pid=$(".p-id",view),av=$(".p-id .avatar",view),yy=Math.min(Math.max(y,0),200);
      if(pid){pid.style.transform=move?`translate3d(0,${(yy*.3).toFixed(1)}px,0)`:"";pid.style.opacity=move?Math.max(0,1-yy/160).toFixed(3):""}
      if(av){av.style.transform=move?`scale(${(1-yy/200*.22).toFixed(4)})`:"";av.style.transformOrigin="left center"}
      $("#appbar").classList.toggle("swap",!!pid&&y>pid.offsetTop+pid.offsetHeight-8);
    }else $("#appbar").classList.remove("swap");
  });
}
view.addEventListener("scroll",onScroll,{passive:true});
function carouselScale(){}
document.addEventListener("scroll",e=>{if(e.target&&e.target.id==="car-scroll")requestAnimationFrame(()=>carouselScale(e.target))},true);

/* Results count runs up to its value */
function tick(root){
  const el=$("[data-count]",root);if(!el||!canMove())return;const n=+el.dataset.count;if(n<2)return;
  const t0=performance.now(),dur=600;const step=t=>{const k=Math.min(1,(t-t0)/dur);el.textContent=Math.round(n*(1-Math.pow(1-k,4)));if(k<1)requestAnimationFrame(step)};el.textContent="0";requestAnimationFrame(step);
}
const bump=el=>{if(!el||!canMove())return;el.classList.remove("bump");void el.offsetWidth;el.classList.add("bump")};
window.addEventListener("resize",()=>{placeInd();onScroll()});

/* ---------- More motion: shared avatar, sheet stacking, FLIP lists, rolling numbers ---------- */
let rollNext=false;
const PTR_RING=`<svg class="ptr-ring" viewBox="0 0 24 24" width="24" height="24" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="9" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-dasharray="56.5" stroke-dashoffset="56.5" transform="rotate(-90 12 12)"/></svg>`;
function stagger(els,base,step,max){if(!canMove())return;els.slice(0,max).forEach((el,i)=>el.animate([{opacity:0,transform:"translate3d(0,12px,0)"},{opacity:1,transform:"none"}],{duration:440,delay:base+i*step,easing:EASE_IOS,fill:"backwards"}))}
function stackBg(on){
  if(on&&!canMove())return;const a=$("#appbar"),tb=$("#tabbar");
  if(on){const t=a.offsetTop,b=tb.offsetTop+tb.offsetHeight,cy=(t+b)/2;[a,views,tb].forEach(e=>e.style.transformOrigin=`50% ${cy-e.offsetTop}px`)}
  screen.classList.toggle("stacked",on);
}
/* Layout position inside the scrolling view, ignoring transforms (the view may be mid-transition) */
function layoutRect(el){
  let x=0,y=0,n=el;while(n&&n!==view){x+=n.offsetLeft;y+=n.offsetTop;n=n.offsetParent}if(n!==view)return null;
  for(let p=el.parentElement;p&&p!==view;p=p.parentElement){x-=p.scrollLeft||0}
  const vr=views.getBoundingClientRect();return {left:vr.left+x,top:vr.top+y-view.scrollTop,width:el.offsetWidth,height:el.offsetHeight};
}
function prepFlight(av){
  if(!canMove()||!av)return null;const r=av.getBoundingClientRect(),vr=views.getBoundingClientRect();
  if(!r.width||r.bottom<vr.top||r.top>vr.bottom)return null;
  const cs=getComputedStyle(av),node=av.cloneNode(true);av.setAttribute("data-flying","");
  return {node,r,bg:cs.backgroundColor,sh:cs.boxShadow&&cs.boxShadow!=="none"?cs.boxShadow:"rgba(0, 169, 224, 0) 0px 0px 0px 0px",fs:cs.fontSize};
}
function findAvatar(id){return $(`[data-card="${id}"] .avatar`,view)||$(`.mini[data-id="${id}"] .avatar`,view)||$(`.row[data-id="${id}"] .avatar`,view)}
function launchFlight(f,dest){
  if(!f||!dest)return;const d=layoutRect(dest),vr=views.getBoundingClientRect();
  if(!d||d.top+d.height<vr.top+8||d.top>vr.bottom-8)return;
  const sr=screen.getBoundingClientRect(),c=f.node,dcs=getComputedStyle(dest),s=d.width/f.r.width;
  c.removeAttribute("data-flying");c.classList.add("flyer");c.setAttribute("aria-hidden","true");
  Object.assign(c.style,{position:"absolute",left:f.r.left-sr.left+"px",top:f.r.top-sr.top+"px",width:f.r.width+"px",height:f.r.height+"px",margin:"0",zIndex:"15",transformOrigin:"0 0",fontSize:f.fs,animation:"none",transform:"none",pointerEvents:"none"});
  screen.appendChild(c);dest.style.visibility="hidden";
  const ring=dcs.boxShadow&&dcs.boxShadow!=="none"?`rgb(0, 169, 224) 0px 0px 0px ${(4/s).toFixed(2)}px`:"rgba(0, 169, 224, 0) 0px 0px 0px 0px";
  const a=c.animate([{transform:"translate(0px,0px) scale(1)",backgroundColor:f.bg,boxShadow:f.sh},
    {transform:`translate(${(d.left-f.r.left).toFixed(1)}px,${(d.top-f.r.top).toFixed(1)}px) scale(${s.toFixed(4)})`,backgroundColor:dcs.backgroundColor,boxShadow:ring}],{duration:520,easing:EASE_IOS,fill:"forwards"});
  a.onfinish=a.oncancel=()=>{dest.style.visibility="";c.remove()};
}
/* FLIP: remember where cards were, re-render, then glide each from its old place */
function captureCards(){const m=new Map();$$("[data-card]",view).forEach(c=>m.set(c.dataset.card,c.getBoundingClientRect().top));return m}
function flipCards(before){
  if(!canMove())return;
  $$("[data-card]",view).forEach(c=>{const b=before.get(c.dataset.card),a=c.getBoundingClientRect().top;
    if(b!=null){const dy=b-a;if(Math.abs(dy)>1)c.animate([{transform:`translate3d(0,${dy.toFixed(1)}px,0)`},{transform:"none"}],{duration:560,easing:EASE_IOS})}
    else c.animate([{opacity:0,transform:"scale(.96)"},{opacity:1,transform:"none"}],{duration:420,delay:140,easing:EASE_IOS,fill:"backwards"})});
}
function collapseOut(el,done){
  const h=el.offsetHeight;el.style.overflow="hidden";
  el.animate(ZOOM_OUT_KF,{duration:240,easing:"ease-in",fill:"forwards"}).onfinish=()=>
    el.animate([{height:h+"px",marginTop:"0px",opacity:0},{height:"0px",marginTop:"-12px",opacity:0}],{duration:320,easing:EASE_IOS,fill:"forwards"}).onfinish=done;
}
function rollNumber(el,from,to){
  if(!el)return;if(from===to||!canMove()){el.textContent=to;return}
  const up=to>from;el.innerHTML=`<span class="roll"><span class="r-new">${to}</span><span class="r-old" aria-hidden="true">${from}</span></span>`;
  const nw=$(".r-new",el),od=$(".r-old",el),o={duration:440,easing:EASE_IOS};
  nw.animate([{transform:`translate3d(0,${up?100:-100}%,0)`,opacity:0},{transform:"none",opacity:1}],o);
  od.animate([{transform:"none",opacity:1},{transform:`translate3d(0,${up?-100:100}%,0)`,opacity:0}],{...o,fill:"forwards"}).onfinish=()=>{if(el.contains(nw))el.textContent=to};
}

/* ---------- Splash ---------- */
let spT=null;
function playSplash(){
  const Sp=$("#splash");clearTimeout(spT);
  Sp.innerHTML=`<div class="sp-glow" aria-hidden="true"></div><span class="sp-ring" aria-hidden="true"></span><span class="sp-ring" aria-hidden="true"></span><span class="sp-ring" aria-hidden="true"></span>
    <div class="sp-icon" aria-hidden="true"><!--APP_ICON--></div><div class="sp-word" role="img" aria-label="UTSW MyCare"><!--LOGO_REVERSED--></div>
    <div class="sp-bar" aria-hidden="true"><i></i></div><p class="sr-only" role="status">UTSW MyCare is opening</p>`;
  Sp.classList.remove("out");Sp.hidden=false;setInert(true);
  /* what sits underneath when the splash lifts: onboarding on first run, otherwise the app */
  /* every launch of the prototype runs the full first-run flow so reviewers can always walk it */
  if($("#ob").hidden)openOnboarding();
  Sp.onclick=endSplash;
  spT=setTimeout(endSplash,rm()?700:2500);
}
function endSplash(){
  const Sp=$("#splash");if(Sp.hidden||Sp.classList.contains("out"))return;clearTimeout(spT);
  const done=()=>{Sp.hidden=true;Sp.innerHTML="";Sp.classList.remove("out");
    if($("#ob").hidden){setInert(false);if(top().v==="home"){S.heroDone=false;render("fade",{scroll:0})}}
    else setTimeout(()=>$(".ob-slide.on h2",$("#ob"))?.focus(),60)};
  if(!canMove())return done();
  Sp.classList.add("out");setTimeout(done,520);
}

